#!/usr/bin/env bash
set -euo pipefail
src=$1 dst=$2
mkdir -p "$dst"
find "$src" -type f -mtime -1 -exec cp -p {} "$dst" \;

#!/usr/bin/env bash
set -euo pipefail
find . -type f | awk -F. 'NF>1 {print tolower($NF)} NF==1 {print "(none)"}' | sort | uniq -c | sort -nr

#!/usr/bin/env bash
set -euo pipefail
for f in *.tar.gz *.tgz *.tar.bz2 *.tar.xz; do
  [ -e "$f" ] || continue
  case $f in
    *.tar.gz|*.tgz) tar -xzf "$f";;
    *.tar.bz2)      tar -xjf "$f";;
    *.tar.xz)       tar -xJf "$f";;
  esac
done

#!/usr/bin/env bash
set -euo pipefail
tail -F -n0 "$1" | while IFS= read -r line; do
  case $line in
    *ERROR*) printf '%s\n' "$line" >> errors.log;;
    *WARN*)  printf '%s\n' "$line" >> warnings.log;;
  esac
done

#!/usr/bin/env bash
set -euo pipefail
du -shc -- *./* 2>/dev/null | tail -1

#!/usr/bin/env bash
set -euo pipefail
awk '{printf "%.1f\n", ($1 - 32) * 5 / 9}' temps.txt

#!/usr/bin/env bash
set -euo pipefail
find . -type f -exec sha256sum {} + | sort | awk '{h=$1; $1=""; if (h==prev) {print prevf; print $0} prev=h; prevf=$0}'
